-- ----------------------------
-- Table structure for im_channel_message
-- ----------------------------
DROP TABLE IF EXISTS `im_channel_message`;
CREATE TABLE `im_channel_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `channel_id` bigint NOT NULL COMMENT '频道编号；冗余 im_channel_material.channel_id 便于检索',
  `material_id` bigint NOT NULL COMMENT '关联素材编号',
  `type` smallint NOT NULL COMMENT '消息类型',
  `content` varchar(8192) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '消息内容；推送 payload JSON 快照；不含富文本正文',
  `receiver_user_ids` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '接收人编号列表；逗号分隔；为空表示全员',
  `send_time` datetime NOT NULL COMMENT '发送时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_im_channel_message_channel_send`(`channel_id` ASC, `send_time` ASC) USING BTREE,
  INDEX `idx_im_channel_message_material`(`material_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IM 频道消息表';

