-- ----------------------------
-- Table structure for im_friend
-- ----------------------------
DROP TABLE IF EXISTS `im_friend`;
CREATE TABLE `im_friend`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id` bigint NOT NULL COMMENT '用户编号',
  `friend_user_id` bigint NOT NULL COMMENT '好友用户编号',
  `silent` bit(1) NULL DEFAULT b'0' COMMENT '是否免打扰',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '好友状态（0=正常，1=已解除）',
  `add_time` datetime NULL DEFAULT NULL COMMENT '添加好友时间',
  `delete_time` datetime NULL DEFAULT NULL COMMENT '删除好友时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  `display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '好友展示备注（仅自己可见）',
  `add_source` tinyint NULL DEFAULT NULL COMMENT '添加来源；参见 ImFriendAddSourceEnum 枚举',
  `pinned` bit(1) NULL DEFAULT b'0' COMMENT '是否置顶联系人',
  `blocked` bit(1) NULL DEFAULT b'0' COMMENT '是否拉黑',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_im_friend_user_friend`(`user_id` ASC, `friend_user_id` ASC) USING BTREE,
  INDEX `idx_sync`(`user_id` ASC, `update_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14106 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IM 好友关系表';

-- ----------------------------
-- Records of im_friend
-- ----------------------------
