-- ----------------------------
-- Table structure for im_friend_request
-- ----------------------------
DROP TABLE IF EXISTS `im_friend_request`;
CREATE TABLE `im_friend_request`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `from_user_id` bigint NOT NULL COMMENT '发起方用户编号',
  `to_user_id` bigint NOT NULL COMMENT '接收方用户编号',
  `handle_result` tinyint NOT NULL DEFAULT 0 COMMENT '处理结果；0未处理；1同意；2拒绝',
  `apply_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请理由（发起方填写）',
  `handle_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处理理由（接收方拒绝时可选填）',
  `display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发起方对接收方的备注；同意后写入 A 侧 im_friend.display_name',
  `add_source` tinyint NULL DEFAULT NULL COMMENT '添加来源；参见 ImFriendAddSourceEnum 枚举',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_im_friend_request`(`from_user_id` ASC, `to_user_id` ASC, `tenant_id` ASC) USING BTREE,
  INDEX `idx_to_user_handle`(`to_user_id` ASC, `handle_result` ASC) USING BTREE,
  INDEX `idx_from_user`(`from_user_id` ASC) USING BTREE,
  INDEX `idx_sync_from`(`from_user_id` ASC, `update_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_sync_to`(`to_user_id` ASC, `update_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IM 好友申请记录表';

-- ----------------------------
-- Records of im_friend_request
-- ----------------------------
BEGIN;
INSERT INTO `im_friend_request` (`id`, `from_user_id`, `to_user_id`, `handle_result`, `apply_content`, `handle_content`, `display_name`, `add_source`, `handle_time`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (6, 1, 103, 1, '我是\"IM 联调测试群\"的OPENLAB BS', NULL, NULL, 2, '2026-05-04 11:00:34', '1', '2026-05-04 10:31:28', '103', '2026-05-04 11:00:34', b'0', 1);
COMMIT;

-- ----------------------------
-- Table structure for im_group
-- ----------------------------
DROP TABLE IF EXISTS `im_group`;
CREATE TABLE `im_group`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '群名称',
  `owner_user_id` bigint NOT NULL COMMENT '群主用户编号',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '群头像',
  `notice` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '群公告',
  `banned` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否封禁',
  `banned_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封禁原因',
  `banned_time` datetime NULL DEFAULT NULL COMMENT '封禁时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '群状态 0=正常 1=已解散',
  `dissolved_time` datetime NULL DEFAULT NULL COMMENT '解散时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  `pinned_message_ids` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '群置顶消息编号列表，逗号分隔',
  `muted_all` bit(1) NULL DEFAULT b'0' COMMENT '是否全群禁言',
  `join_approval` bit(1) NOT NULL DEFAULT b'0' COMMENT '进群是否需群主 / 管理员审批；false 自由进群，true 需审批',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10087 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IM 群组表';

