-- ----------------------------
-- Table structure for im_group_message
-- ----------------------------
DROP TABLE IF EXISTS `im_group_message`;
CREATE TABLE `im_group_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `client_message_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户端消息编号，用于发送幂等',
  `sender_id` bigint NOT NULL COMMENT '发送人编号',
  `group_id` bigint NOT NULL COMMENT '群编号',
  `type` smallint NOT NULL COMMENT '消息类型',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容，JSON 格式',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '消息状态',
  `send_time` datetime NOT NULL COMMENT '发送时间',
  `receiver_user_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '定向接收用户编号列表，以逗号分隔（如 1,2），为空表示全员可见',
  `at_user_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '@目标用户编号列表，以逗号分隔（如 1,2,3）',
  `receipt_status` tinyint NOT NULL DEFAULT 0 COMMENT '回执状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_im_group_sender_client_msg`(`sender_id` ASC, `client_message_id` ASC) USING BTREE,
  INDEX `idx_im_group_group_id_id`(`group_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51878 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IM 群聊消息表';

-- ----------------------------
-- Records of im_group_message
