-- ----------------------------
-- Table structure for im_group_request
-- ----------------------------
DROP TABLE IF EXISTS `im_group_request`;
CREATE TABLE `im_group_request`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `group_id` bigint NOT NULL COMMENT '群编号',
  `user_id` bigint NOT NULL COMMENT '申请人 / 被邀请人用户编号',
  `inviter_user_id` bigint NULL DEFAULT NULL COMMENT '邀请人用户编号；NULL=主动申请；非NULL=被邀请待审批',
  `apply_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请理由',
  `add_source` tinyint NULL DEFAULT NULL COMMENT '加入来源；参见 ImGroupAddSourceEnum',
  `handle_result` tinyint NOT NULL DEFAULT 0 COMMENT '处理结果；0未处理 1同意 2拒绝',
  `handle_user_id` bigint NULL DEFAULT NULL COMMENT '处理人用户编号',
  `handle_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '处理理由',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_im_group_request`(`group_id` ASC, `user_id` ASC, `tenant_id` ASC) USING BTREE,
  INDEX `idx_group_handle`(`group_id` ASC, `handle_result` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC, `id` ASC) USING BTREE,
  INDEX `idx_sync`(`group_id` ASC, `update_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'IM 加群申请记录表';

-- ----------------------------
-- Records of im_group_request
-- ----------------------------
BEGIN;
INSERT INTO `im_group_request` (`id`, `group_id`, `user_id`, `inviter_user_id`, `apply_content`, `add_source`, `handle_result`, `handle_user_id`, `handle_content`, `handle_time`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, 10007, 104, 1, NULL, NULL, 1, 103, NULL, '2026-05-06 17:47:00', '1', '2026-05-06 17:46:13', '103', '2026-05-06 17:47:00', b'0', 1), (2, 10005, 104, 1, NULL, NULL, 1, 1, NULL, '2026-05-06 21:31:00', '1', '2026-05-06 21:21:41', '1', '2026-05-06 21:31:00', b'0', 1), (3, 10005, 100, 103, NULL, NULL, 1, 1, NULL, '2026-05-07 00:01:26', '103', '2026-05-06 21:34:45', '1', '2026-05-07 00:01:26', b'0', 1);
COMMIT;

-- ----------------------------
-- Table structure for im_private_message
-- ----------------------------
DROP TABLE IF EXISTS `im_private_message`;
CREATE TABLE `im_private_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `client_message_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户端消息编号，用于发送幂等',
  `sender_id` bigint NOT NULL COMMENT '发送人编号',
  `receiver_id` bigint NOT NULL COMMENT '接收人编号',
  `type` smallint NOT NULL COMMENT '消息类型',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容，JSON 格式',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '消息',
  `receipt_status` tinyint NOT NULL DEFAULT 0 COMMENT 'å›žæ‰§çŠ¶æ€',
  `send_time` datetime NOT NULL COMMENT '发送时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_im_private_sender_client_msg`(`sender_id` ASC, `client_message_id` ASC) USING BTREE,
  INDEX `idx_im_private_sender_id_id`(`sender_id` ASC, `id` ASC) USING BTREE,
  INDEX `idx_im_private_receiver_id_id`(`receiver_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41222 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IM 私聊消息表';

