-- ----------------------------
-- Table structure for im_rtc_call
-- ----------------------------
DROP TABLE IF EXISTS `im_rtc_call`;
CREATE TABLE `im_rtc_call`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `room` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务通话编号',
  `conversation_type` tinyint NOT NULL COMMENT '会话类型',
  `media_type` tinyint NOT NULL COMMENT '媒体类型',
  `inviter_user_id` bigint NOT NULL COMMENT '发起人用户编号',
  `group_id` bigint NULL DEFAULT NULL COMMENT '群编号',
  `status` tinyint NOT NULL COMMENT '通话状态',
  `end_reason` tinyint NULL DEFAULT NULL COMMENT '结束原因',
  `start_time` datetime NOT NULL COMMENT '发起时间',
  `accept_time` datetime NULL DEFAULT NULL COMMENT '接通时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_room`(`room` ASC) USING BTREE,
  INDEX `idx_inviter_time`(`inviter_user_id` ASC, `start_time` DESC) USING BTREE,
  INDEX `idx_group_status`(`group_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_group_time`(`group_id` ASC, `start_time` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 97 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'IM 通话记录表';

-- ----------------------------
-- Records of im_rtc_call
-- ----------------------------
